// 1. Read intake parameters from Webhook payload
const body = $input.first().json.body || {};
const targetRole = body.target_role || 'Full-Stack AI Engineer';
const skills = Array.isArray(body.skills) ? body.skills : ['React', 'n8n', 'Pinecone'];
const minFixed = Number(body.min_fixed_budget) || 500;
const minHourly = Number(body.min_hourly_rate) || 40;

// 2. Upwork RFP Job Pool (simulating active RSS feed postings)
const rawFeedItems = [
  {
    title: `Senior ${targetRole} Needed for AI Workflow Automation`,
    link: "https://www.upwork.com/jobs/~01a2b3c4d5e6f7a8b9",
    description: `Budget: $1,500. We are seeking an expert ${targetRole} to build an end-to-end automated RFP intelligence pipeline using ${skills.join(', ')}. Must have experience with vector databases and LLM orchestration.`,
    pubDate: new Date().toUTCString(),
    guid: "job_upwork_rfp_01"
  },
  {
    title: "Build Production RAG & Vector Search Integration",
    link: "https://www.upwork.com/jobs/~02b3c4d5e6f7a8b9c0",
    description: `Hourly Rate: $50-$80/hr. Seeking a skilled developer to build a RAG application with Pinecone and FastAPI. Tech stack: ${skills.slice(0, 3).join(', ')}. Clean architecture and high accuracy required.`,
    pubDate: new Date(Date.now() - 3600000).toUTCString(),
    guid: "job_upwork_rfp_02"
  },
  {
    title: "n8n Custom Nodes & Webhook Integration Engineer",
    link: "https://www.upwork.com/jobs/~04c5d6e7f8a9b0c1d2",
    description: `Budget: $850. Need an n8n workflow expert to automate lead intake and database sync. Skills needed: n8n, Webhooks, REST APIs, ${skills[0] || 'React'}.`,
    pubDate: new Date(Date.now() - 7200000).toUTCString(),
    guid: "job_upwork_rfp_03"
  }
];

// 3. Regex Normalization & Filtering Loop
const filteredItems = [];
for (const item of rawFeedItems) {
  const fullText = `${item.title} ${item.description}`;
  let budgetType = 'Fixed';
  let budgetValue = 0;

  const hourlyMatch = fullText.match(/\$(\d+(?:\.\d{1,2})?)\s*\-\s*\$(\d+(?:\.\d{1,2})?)\/hr/i) || fullText.match(/Hourly Rate:\s*\$(\d+(?:\.\d{1,2})?)/i);
  const fixedMatch = fullText.match(/Budget:\s*\$(\d{1,3}(?:,\d{3})*|\d+)/i) || fullText.match(/\$(\d{1,3}(?:,\d{3})*|\d+)/);

  if (hourlyMatch) {
    budgetType = 'Hourly';
    budgetValue = parseFloat(hourlyMatch[1]);
  } else if (fixedMatch) {
    budgetType = 'Fixed';
    budgetValue = parseFloat(fixedMatch[1].replace(/,/g, ''));
  }

  if (budgetType === 'Fixed' && budgetValue < minFixed) continue;
  if (budgetType === 'Hourly' && budgetValue < minHourly) continue;

  filteredItems.push({
    json: {
      job_title: item.title,
      job_link: item.link,
      description: item.description,
      budget_type: budgetType,
      budget_value: budgetValue,
      pubDate: item.pubDate,
      guid: item.guid
    }
  });
}

return filteredItems;

const webhookData = $("Webhook Trigger").first().json.body || {};
const targetRole = (webhookData.target_role || '').toLowerCase();
const userSkills = (webhookData.skills || []).map(s => s.toLowerCase());
const proofOfWork = webhookData.proof_of_work || {};

const items = $input.all();
const scoredItems = [];

for (const item of items) {
  const job = item.json;
  const title = (job.job_title || '').toLowerCase();
  const desc = (job.description || '').toLowerCase();
  const fullText = `${title} ${desc}`;

  let matchedSkillsCount = 0;
  for (const skill of userSkills) {
    if (skill && fullText.includes(skill)) {
      matchedSkillsCount++;
    }
  }

  const skillRatio = userSkills.length > 0 ? matchedSkillsCount / userSkills.length : 0.8;
  const roleMatch = fullText.includes(targetRole) ? 35 : 20;
  const baseScore = Math.min(98, Math.max(65, Math.round(roleMatch + (skillRatio * 60))));

  const painPoints = [];
  if (fullText.includes('automation') || fullText.includes('workflow')) {
    painPoints.push('Manual RFP triage and slow workflow execution');
  }
  if (fullText.includes('rag') || fullText.includes('vector') || fullText.includes('pinecone')) {
    painPoints.push('Retrieval latency and accuracy bottlenecks in vector search');
  }
  if (fullText.includes('n8n') || fullText.includes('webhook')) {
    painPoints.push('Complex multi-system integration and payload syncing');
  }
  if (painPoints.length === 0) {
    painPoints.push('Need for clean, scalable technical implementation');
  }

  scoredItems.push({
    json: {
      ...job,
      fit_score: baseScore,
      pain_points: painPoints,
      proof_of_work_used: {
        title: proofOfWork.title || 'Nexus RAG',
        url: proofOfWork.url || 'https://nexus-rag.vercel.app',
        context: proofOfWork.context || 'Production RAG pipeline'
      }
    }
  });
}

scoredItems.sort((a, b) => b.json.fit_score - a.json.fit_score);
return scoredItems;

const webhookData = $("Webhook Trigger").first().json.body || {};
const tone = webhookData.proposal_tone || 'Direct Technical';

const items = $input.all();
const draftedItems = [];

for (const item of items) {
  const job = item.json;
  const pow = job.proof_of_work_used || {};
  const mainPainPoint = (job.pain_points && job.pain_points[0]) ? job.pain_points[0] : 'technical bottleneck';

  let proposalText = '';

  if (tone === 'Direct Technical') {
    proposalText = `Your system is currently bottlenecked by ${mainPainPoint.toLowerCase()}. I specialize in solving this exact architecture challenge using scalable backend pipelines.

I built ${pow.title || 'a production system'} (${pow.url || ''}) which specifically resolves this by implementing: ${pow.context || 'high-throughput processing'}.

Execution Plan:
• Phase 1: Audit payload structure and establish clean data schemas.
• Phase 2: Deploy robust processing pipeline with error-handling and fallback logic.
• Phase 3: Deliver verified integration tests and documentation.

Let's connect for a 10-minute technical scoping call to align on your architecture timeline.`;
  } else if (tone === 'Concise Executive') {
    proposalText = `I read your requirements for ${job.job_title}. The primary technical challenge is ${mainPainPoint.toLowerCase()}.

Here is a live production demo solving this: ${pow.url || ''} (${pow.title || 'Live Demo'}).

Key Deliverables:
1. Production-ready workflow pipeline.
2. Complete automated integration.
3. End-to-end verification.

Available to start immediately. Let's schedule a call to review scoping.`;
  } else {
    proposalText = `Looking at your project for ${job.job_title}, the key area to address right away is ${mainPainPoint.toLowerCase()}.

I recently deployed ${pow.title || 'a similar project'} (${pow.url || ''}) to address this exact use case: ${pow.context || 'automated processing'}.

I can deliver this efficiently with clear milestones:
• Core architecture implementation
• Verification & testing
• Handoff documentation

Looking forward to discussing your technical requirements.`;
  }

  draftedItems.push({
    json: {
      ...job,
      proposal: proposalText
    }
  });
}

return draftedItems;
